/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic [2:0] a,
    output logic [15:0] q
);
    always_comb begin
        case (a)
            3'd0: q = 16'h1232;
            3'd1: q = 16'haee0;
            3'd2: q = 16'h27d4;
            3'd3: q = 16'h5a0e;
            3'd4: q = 16'h2066;
            3'd5: q = 16'h64ce;
            3'd6: q = 16'hc526;
            3'd7: q = 16'h2f19;
            default: q = 16'hxxxx;
        endcase
    end
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic [2:0] a;
    wire [15:0] q;
    logic [15:0] expected [0:7];
    integer i;
    integer pass;
    TopModule dut (.a(a), .q(q));
    initial begin
        expected[0] = 16'"'h1232;
        expected[1] = 16'haee0;
        expected[2] = 16'h27d4;
        expected[3] = 16'h5a0e;
        expected[4] = 16'h2066;
        expected[5] = 16'h64ce;
        expected[6] = 16'hc526;
        expected[7] = 16'h2f19;
        a = 3'bxxx;
        #1;
        if (q "'!== 16'"'hxxxx) "'$fatal(1, "Unknown input mismatch");
        for (pass = 0; pass < 2; pass = pass + 1) begin
            for (i = 0; i < 8; i = i + 1) begin
                a = (pass == 0) ? 3'"'(i) : 3'(7-i);
                #1;
                if (q "'!== expected[a])
                    $fatal(1, "Mismatch a=%0d q=%h expected=%h", a, q, expected[a]);
            end
        end
        $display("PASS: all eight entries checked in both orders, plus unknown input");
        $finish;
    end
    initial begin
        #100;
        $fatal(1, "Timeout");
    end
endmodule
EOF
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > compile.log 2>&1
compile_status=$?
cat compile.log
printf '"'compile_exit=%s\\n' \""'$compile_status" > check_status.log
if [ "$compile_status" -eq 0 ]; then
    timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > simulation.log 2>&1
    simulation_status=$?
    printf '"'simulation_exit=%s\\n' \""'$simulation_status" >> check_status.log
    cat simulation.log
fi'

